192	/* One bit per syscall number (0..511): "print vlinux: ENOSYS <nr> once" --
193	 * the diagnostic should not repeat if the same unimplemented syscall is
194	 * hit again later. */
195	static unsigned char g_enosys_seen[64];
196	
197	static int enosys_already_seen(unsigned long nr)
198	{
199	  if (nr >= 512) return 0; /* out of the table's range: always print */
200	  const unsigned long byte = nr / 8, bit = nr % 8;
201	  if (g_enosys_seen[byte] & (unsigned char) (1u << bit)) return 1;
202	  g_enosys_seen[byte] |= (unsigned char) (1u << bit);
203	  return 0;
204	}
