206	static long sys_writev(int fd, const struct vlinux_iovec* iov, int iovcnt)
207	{
208	  long total = 0;
209	  for (int i = 0; i < iovcnt; ++i) {
210	    const ssize_t n = _write(fd, iov[i].iov_base, iov[i].iov_len);
211	    if (n < 0) return total ? total : n;
212	    total += n;
213	    if ((size_t) n < iov[i].iov_len) break; /* short write */
214	  }
215	  return total;
216	}
