316	static long sys_fstat(int fd, struct vlinux_stat* buf)
317	{
318	  long r = htif_syscall(VH_SYS_FSTAT, (uint64_t) fd, WIN_DATA_VA, 0, 0);
319	  if (r == 0) {
320	    unsigned int mode; unsigned long size;
321	    host_stat_mode_size(0, &mode, &size);
322	    fill_stat_from_host(buf, mode, size);
323	  }
324	  return r;
325	}
