327	/* fstatat honors dirfd and AT_SYMLINK_NOFOLLOW natively on the host side
328	 * (its own fstatat() call), so both forward as-is -- no AT_FDCWD special
329	 * case needed here (unlike openat, this host handler already threads
330	 * every argument fstatat's real ABI has). This is also where glibc's
331	 * stat()/lstat() land: riscv64 has no bare stat/lstat syscalls. */
332	static long sys_fstatat(int dirfd, const char* path, struct vlinux_stat* buf,
333	                        int flags)
334	{
335	  size_t stoff = htif_win_store_str(0, path);
336	  /* stoff+24: room for host_stat_mode_size's aligned scratch block right
337	   * after the path string, same bound vplat's own _fstatat/_stat apply. */
338	  if (stoff == (size_t) -1 || stoff + 24 > WIN_DATA_SIZE) return -EINVAL;
339	  long r = htif_syscall(VH_SYS_FSTATAT, (uint64_t) dirfd, WIN_DATA_VA,
340	                        WIN_DATA_VA + stoff, (uint64_t) flags);
341	  if (r == 0) {
342	    unsigned int mode; unsigned long size;
343	    host_stat_mode_size(stoff, &mode, &size);
344	    fill_stat_from_host(buf, mode, size);
345	  }
346	  return r;
347	}
348	
349	/* statx: same host round trip as fstatat (mode+size only), translated
350	 * into struct statx. stx_mask reports ONLY the fields actually filled
351	 * (TYPE/MODE/NLINK/UID/GID/SIZE) -- per statx(2), a caller must not trust
352	 * a field whose mask bit is clear, so this is the correct "basic mask"
353	 * contract, not a shortcut: blksize/blocks are always-filled best-effort
354	 * (real filesystems provide them unconditionally per the man page), while
355	 * timestamps/ino stay zero and unclaimed since nothing here has them. */
356	static long sys_statx(int dirfd, const char* path, int flags,
357	                      struct vlinux_statx* buf)
358	{
359	  size_t stoff = htif_win_store_str(0, path);
360	  if (stoff == (size_t) -1 || stoff + 24 > WIN_DATA_SIZE) return -EINVAL;
361	  long r = htif_syscall(VH_SYS_FSTATAT, (uint64_t) dirfd, WIN_DATA_VA,
362	                        WIN_DATA_VA + stoff, (uint64_t) flags);
363	  if (r == 0) {
364	    unsigned int mode; unsigned long size;
365	    host_stat_mode_size(stoff, &mode, &size);
366	    for (size_t i = 0; i < sizeof(*buf); ++i) ((char*) buf)[i] = 0;
367	    buf->stx_mask = STATX_TYPE | STATX_MODE | STATX_NLINK | STATX_UID |
368	                    STATX_GID | STATX_SIZE;
369	    buf->stx_mode = (unsigned short) mode;
370	    buf->stx_nlink = 1;
371	    buf->stx_size = size;
372	    buf->stx_blksize = 4096;
373	    buf->stx_blocks = (size + 511) / 512;
374	  }
375	  return r;
376	}
