378	/* faccessat(2) (syscall 48, distinct from the faccessat() library
379	 * function) takes exactly 3 arguments -- (dirfd, path, mode), no flags --
380	 * so regs[REG_A3] here is NOT a flags argument to honor; the libc wrapper
381	 * implements AT_SYMLINK_NOFOLLOW/AT_EACCESS itself when needed, in
382	 * userspace, without a 4th syscall argument. Always pass 0. */
383	static long sys_faccessat(int dirfd, const char* path, int mode)
384	{
385	  size_t stoff = htif_win_store_str(0, path);
386	  if (stoff == (size_t) -1) return -EINVAL;
387	  return htif_syscall(VH_SYS_FACCESSAT, (uint64_t) dirfd, WIN_DATA_VA,
388	                      (uint64_t) mode, 0);
389	}
