391	/* getcwd(2): the host's VH_SYS_GETCWD returns the buffer's ADDRESS on
392	 * success / 0 on failure (a char*-returning getcwd() convention, shared
393	 * with vplat's own _getcwd), not the Linux syscall's "bytes written
394	 * including NUL" convention -- translate by measuring the string vlinux
395	 * just read back. */
396	static long sys_getcwd(char* buf, unsigned long size)
397	{
398	  uint64_t n = size > WIN_DATA_SIZE ? WIN_DATA_SIZE : size;
399	  intptr_t ret = htif_syscall(VH_SYS_GETCWD, WIN_DATA_VA, n, 0, 0);
400	  if (ret == 0) return -ERANGE;
401	  htif_win_load(buf, 0, n);
402	  size_t len = 0;
403	  while (len < n && buf[len]) ++len;
404	  return (long) (len + 1);
405	}
406	
407	/* sysinfo(2): totalram/freeram from mm.c's own manifest-supplied RAM
408	 * size (freeram == totalram, an optimistic overestimate -- there is no
409	 * cheap way to account for what mm.c's two arenas have already handed
410	 * out, and callers use this for a rough sizing heuristic, not a
411	 * correctness-critical value). Everything else (load averages, swap,
412	 * shared/buffer/highmem, process count) has no meaning on a single-hart,
413	 * single-process, no-swap target, so it is reported as zero/absent. */
414	static void sys_sysinfo(struct vlinux_sysinfo* si)
415	{
416	  for (size_t i = 0; i < sizeof(*si); ++i) ((char*) si)[i] = 0;
417	  si->totalram = mm_total_ram();
418	  si->freeram = si->totalram;
419	  si->procs = 1;
420	  si->mem_unit = 1;
421	}
422	
423	/* {sec, usec}, both u64 slots -- an 8-aligned, 16-byte (2x8) window load,
424	 * compliant with htif_win_load's alignment contract (see U5's
425	 * host_stat_mode_size comment). Mirrors vplat_syscalls.c's _gettimeofday. */
426	static int host_gettimeofday(long* sec, long* usec)
427	{
428	  if (htif_syscall(VH_SYS_GETTIMEOFDAY, WIN_DATA_VA, 0, 0, 0) != 0) return -1;
429	  uint64_t raw[2];
430	  htif_win_load(raw, 0, sizeof raw);
431	  *sec = (long) raw[0];
432	  *usec = (long) raw[1];
433	  return 0;
434	}
435	
436	/* CLOCK_MONOTONIC has no dedicated host primitive -- only the wall clock
437	 * VH_SYS_GETTIMEOFDAY exposes. Synthesize it as "elapsed time since this
438	 * process's first monotonic query" (captured lazily, once): never goes
439	 * backward under normal operation, same guarantee real CLOCK_MONOTONIC
440	 * gives, at the cost of losing meaning across a host wall-clock step --
441	 * acceptable here since there is no other clock source to build it from. */
442	static long g_mono_base_sec = -1;
443	static long g_mono_base_usec;
444	
445	static long sys_clock_gettime(int clk, struct vlinux_timespec* tp)
446	{
447	  long sec, usec;
448	  if (host_gettimeofday(&sec, &usec) != 0) return -EINVAL;
449	
450	  if (clk == CLOCK_MONOTONIC) {
451	    if (g_mono_base_sec < 0) {
452	      g_mono_base_sec = sec;
453	      g_mono_base_usec = usec;
454	    }
455	    sec -= g_mono_base_sec;
456	    usec -= g_mono_base_usec;
457	    if (usec < 0) {
458	      usec += 1000000;
459	      sec -= 1;
460	    }
461	  } else if (clk != CLOCK_REALTIME) {
462	    return -EINVAL;
463	  }
464	
465	  tp->tv_sec = sec;
466	  tp->tv_nsec = usec * 1000;
467	  return 0;
468	}
469	
470	static long sys_clock_getres(int clk, struct vlinux_timespec* res)
471	{
472	  if (clk != CLOCK_REALTIME && clk != CLOCK_MONOTONIC) return -EINVAL;
473	  if (res) {
474	    res->tv_sec = 0;
475	    res->tv_nsec = 1000; /* 1us: VH_SYS_GETTIMEOFDAY's real resolution */
476	  }
477	  return 0;
478	}
