1	/* See loader.h. Reads the app ELF via newlib's ordinary open/read/lseek --
2	 * already wired to HTIF by ../vplat_syscalls.c (the same file I/O vplat
3	 * uses), so this file carries no HTIF-specific code at all. */
4	#include "loader.h"
5	
6	#include <elf.h>
7	#include <fcntl.h>
8	#include <stdint.h>
9	#include <string.h>
10	#include <unistd.h>
11	
12	#include "hybrid/state_abi.h" /* HYBRID_V_SCRATCH_BYTES */
13	
14	#define LOADER_MAX_PHDRS 32
15	
16	/* vlinux's own region bounds (runtime/linux/vlinux.ld): one source of
17	 * truth, not duplicated here as magic addresses. */
18	extern char _vlinux_base[];
19	extern char _stack[];
20	
21	/* HTIF SimControl device (runtime/htif_client.h): exit/putchar registers
22	 * plus the syscall window (slots + 1984-byte data area) all live in one
23	 * 4 KiB-aligned range from its base. */
24	#define HTIF_MMIO_BASE 0xe0080000UL
25	#define HTIF_MMIO_SIZE 0x1000UL
26	
27	static int range_overlaps(uint64_t vaddr, uint64_t memsz, uint64_t base,
28	                          uint64_t end)
29	{
30	  return vaddr < end && (vaddr + memsz) > base;
31	}
32	
33	/* Reject a PT_LOAD segment that would land on vlinux's own image, the
34	 * V-transport scratch page, or the HTIF MMIO window -- ROADMAP_LINUX_RUNTIME.md
35	 * U9: the V-scratch/window checks were deferred from U3 until a mode that
36	 * actually reserves them (hybrid) existed to test against, but run
37	 * unconditionally here since they are harmless (nothing is ever there
38	 * under fast/cycle) and correctness should not depend on which mode
39	 * booted this image. */
40	static int overlaps_reserved(uint64_t vaddr, uint64_t memsz, uint64_t mem_size)
41	{
42	  const uint64_t vlinux_base = (uint64_t) (uintptr_t) _vlinux_base;
43	  const uint64_t vlinux_end = (uint64_t) (uintptr_t) _stack;
44	  if (range_overlaps(vaddr, memsz, vlinux_base, vlinux_end)) return 1;
45	
46	  const uint64_t scratch_base = mem_size - HYBRID_V_SCRATCH_BYTES;
47	  if (range_overlaps(vaddr, memsz, scratch_base, mem_size)) return 1;
48	
49	  if (range_overlaps(vaddr, memsz, HTIF_MMIO_BASE,
50	                     HTIF_MMIO_BASE + HTIF_MMIO_SIZE))
51	    return 1;
52	
53	  return 0;
54	}
55	
56	static int read_full(int fd, void* buf, size_t len)
57	{
58	  char* p = (char*) buf;
59	  while (len > 0) {
60	    ssize_t n = read(fd, p, len);
61	    if (n <= 0) return -1;
62	    p += n;
63	    len -= (size_t) n;
64	  }
65	  return 0;
66	}
67	
68	int load_elf(const char* path, uint64_t mem_size, struct loaded_elf* out)
69	{
70	  int fd = open(path, O_RDONLY);
71	  if (fd < 0) return -1;
72	
73	  Elf64_Ehdr eh;
74	  if (read_full(fd, &eh, sizeof(eh)) < 0) goto fail;
75	  if (eh.e_ident[EI_MAG0] != ELFMAG0 || eh.e_ident[EI_MAG1] != ELFMAG1 ||
76	      eh.e_ident[EI_MAG2] != ELFMAG2 || eh.e_ident[EI_MAG3] != ELFMAG3 ||
77	      eh.e_ident[EI_CLASS] != ELFCLASS64 || eh.e_machine != EM_RISCV)
78	    goto fail;
79	  if (eh.e_phnum == 0 || eh.e_phnum > LOADER_MAX_PHDRS) goto fail;
80	
81	  Elf64_Phdr phdrs[LOADER_MAX_PHDRS];
82	  if (lseek(fd, (off_t) eh.e_phoff, SEEK_SET) < 0) goto fail;
83	  if (read_full(fd, phdrs, (size_t) eh.e_phnum * sizeof(Elf64_Phdr)) < 0)
84	    goto fail;
85	
86	  uint64_t phdr_vaddr = 0;
87	  uint64_t image_end = 0;
88	  for (unsigned i = 0; i < eh.e_phnum; ++i) {
89	    const Elf64_Phdr* ph = &phdrs[i];
90	    if (ph->p_type != PT_LOAD) continue;
91	    if (overlaps_reserved(ph->p_vaddr, ph->p_memsz, mem_size)) goto fail;
92	
93	    if (lseek(fd, (off_t) ph->p_offset, SEEK_SET) < 0) goto fail;
94	    if (read_full(fd, (void*) (uintptr_t) ph->p_vaddr, ph->p_filesz) < 0)
95	      goto fail;
96	    if (ph->p_memsz > ph->p_filesz)
97	      memset((void*) (uintptr_t) (ph->p_vaddr + ph->p_filesz), 0,
98	             ph->p_memsz - ph->p_filesz);
99	
100	    /* AT_PHDR: the program headers' address AS LOADED. Find the PT_LOAD
101	     * segment whose FILE range covers e_phoff and translate by the same
102	     * offset -- the segment does not necessarily start at the link base
103	     * (ld backs up to fit the ELF header + phdrs on the same page). */
104	    if (phdr_vaddr == 0 && eh.e_phoff >= ph->p_offset &&
105	        eh.e_phoff < ph->p_offset + ph->p_filesz)
106	      phdr_vaddr = ph->p_vaddr + (eh.e_phoff - ph->p_offset);
107	
108	    const uint64_t seg_end = ph->p_vaddr + ph->p_memsz;
109	    if (seg_end > image_end) image_end = seg_end;
110	  }
111	  if (phdr_vaddr == 0) goto fail; /* no PT_LOAD covered the phdrs: malformed */
112	
113	  close(fd);
114	  out->entry = eh.e_entry;
115	  out->phdr_vaddr = phdr_vaddr;
116	  out->phnum = eh.e_phnum;
117	  out->phentsize = eh.e_phentsize;
118	  out->image_end = image_end;
119	  return 0;
120	
121	fail:
122	  close(fd);
123	  return -1;
124	}
