1	/* Linker script for vlinux, the M-mode proxy-kernel skeleton
2	 * (ROADMAP_LINUX_RUNTIME.md). Load base 0x0200_0000, per the roadmap's
3	 * "Guest memory map" table: vlinux owns 0x0200_0000 .. 0x0220_0000
4	 * (2 MiB) for its own text/data/bss AND its stack, kept clear of the
5	 * app image (which links below 0x0200_0000) and the mmap arena (which
6	 * grows down from just below the app's initial stack, above vlinux).
7	 *
8	 * Structurally the same shape as ../andesim.ld (see that file for why
9	 * each piece is where it is); only the base address, the added
10	 * .manifest section, and the stack address differ. Not merged with
11	 * andesim.ld: the two link completely different kinds of images (an
12	 * arbitrary user program spanning up to the whole DRAM window, vs a
13	 * fixed 2 MiB kernel region) and evolve independently.
14	 */
15	
16	ENTRY(_start)
17	
18	SECTIONS {
19	    . = 0x02000000;
20	    /* vlinux's own region start, for the U3 loader's overlap check --
21	     * PROVIDE(_stack = ...) below is the matching end bound. One source of
22	     * truth: loader.c reads these symbols instead of duplicating the
23	     * addresses as C constants. */
24	    PROVIDE(_vlinux_base = .);
25	
26	    .text : {
27	        *(.text.init)
28	        *(.text*)
29	    }
30	
31	    .rodata : {
32	        *(.rodata*)
33	        *(.srodata*)
34	    }
35	
36	    /* Fixed home for the manifest struct so U2's `objcopy
37	     * --update-section .manifest=<blob>` has a stable target. */
38	    .manifest : {
39	        KEEP(*(.manifest))
40	    }
41	
42	    .preinit_array : {
43	        PROVIDE_HIDDEN(__preinit_array_start = .);
44	        KEEP(*(.preinit_array))
45	        PROVIDE_HIDDEN(__preinit_array_end = .);
46	    }
47	    .init_array : {
48	        PROVIDE_HIDDEN(__init_array_start = .);
49	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
50	        KEEP(*(.init_array .ctors))
51	        PROVIDE_HIDDEN(__init_array_end = .);
52	    }
53	    .fini_array : {
54	        PROVIDE_HIDDEN(__fini_array_start = .);
55	        KEEP(*(SORT_BY_INIT_PRIORITY(.fini_array.*) SORT_BY_INIT_PRIORITY(.dtors.*)))
56	        KEEP(*(.fini_array .dtors))
57	        PROVIDE_HIDDEN(__fini_array_end = .);
58	    }
59	    .eh_frame : { KEEP(*(.eh_frame)) }
60	    .gcc_except_table : { *(.gcc_except_table*) }
61	
62	    .data : {
63	        *(.data*)
64	        *(.sdata*)
65	    }
66	    _edata = .;
67	
68	    .bss : {
69	        *(.bss*)
70	        *(.sbss*)
71	        *(COMMON)
72	    }
73	    _end = .;
74	
75	    /* Stack top = end of vlinux's 2 MiB region (roadmap memory-map
76	     * table); crt0.S reads this via the weak _stack symbol. */
77	    PROVIDE(_stack = 0x02200000);
78	}
