1	/* vplat: one newlib syscall layer that works on EVERY engine.
2	 *
3	 * Replaces -lgloss_vh (semihosting) so a single ELF runs unmodified on
4	 * QEMU (fast), vsim (cycle) and across a hybrid handoff. It is a thin
5	 * newlib adapter over runtime/htif_client.h's HTIF window client -- see
6	 * that header for the wire protocol (UART stdio, SimControl exit, the
7	 * syscall-window file io) and why it must be engine-blind.
8	 */
9	
10	#include <stdint.h>
11	#include <stddef.h>
12	#include <sys/stat.h>
13	#include <unistd.h>
14	
15	#include "htif_client.h"
16	
17	/* ---- SimControl: exit -------------------------------------------------- */
18	
19	#define SIM_EXIT_ADDR 0xe0080000UL
20	
21	/* ---- newlib stubs ------------------------------------------------------
22	 *
23	 * stat family note: the guest's struct bounces through the window BOTH
24	 * ways, so fields the host does not fill keep the caller's values (the
25	 * hosts write pico_stat's st_mode/st_size at their newlib offsets). */
26	
27	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
28	{
29	  if (fd > 2)
30	    return htif_write(fd, ptr, len);
31	  for (size_t i = 0; i < len; ++i)
32	    htif_uart_putc(((const char*) ptr)[i]);
33	  return (ssize_t) len;
34	}
35	
36	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
37	{
38	  if (fd > 2)
39	    return htif_read(fd, buf, len);
40	  return 0; /* no console input on either engine: EOF */
41	}
42	
43	__attribute__((used)) int _fstat(int fd, struct stat* st)
44	{
45	  if (fd > 2) {
46	    htif_win_store(0, st, sizeof(*st));
47	    intptr_t ret = htif_syscall(VH_SYS_FSTAT, fd, WIN_DATA_VA, 0, 0);
48	    if (ret == 0)
49	      htif_win_load(st, 0, sizeof(*st));
50	    return (int) ret;
51	  }
52	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
53	  return 0;
54	}
55	
56	__attribute__((used)) int _isatty(int fd) { return fd <= 2; }
57	
58	__attribute__((used)) int _close(int fd)
59	{
60	  if (fd > 2)
61	    return (int) htif_syscall(VH_SYS_CLOSE, fd, 0, 0, 0);
62	  return 0;
63	}
64	
65	__attribute__((used)) off_t _lseek(int fd, off_t offset, int dir)
66	{
67	  if (fd > 2)
68	    return htif_syscall(VH_SYS_LSEEK, fd, offset, dir, 0);
69	  return 0;
70	}
71	
72	__attribute__((used)) int _open(const char* name, int flags, int mode, ...)
73	{
74	  return (int) htif_call_str(VH_SYS_OPEN, name, flags, mode);
75	}
76	
77	__attribute__((used)) int _openat(int dirfd, const char* name, int flags, ...)
78	{
79	  if (htif_win_store_str(0, name) == (size_t) -1)
80	    return -1;
81	  return (int) htif_syscall(VH_SYS_OPENAT, dirfd, WIN_DATA_VA, flags, 0);
82	}
83	
84	__attribute__((used)) int _stat(const char* file, struct stat* st)
85	{
86	  size_t stoff = htif_win_store_str(0, file);
87	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
88	    return -1;
89	  htif_win_store(stoff, st, sizeof(*st));
90	  intptr_t ret =
91	    htif_syscall(VH_SYS_STAT, WIN_DATA_VA, WIN_DATA_VA + stoff, 0, 0);
92	  if (ret == 0)
93	    htif_win_load(st, stoff, sizeof(*st));
94	  return (int) ret;
95	}
96	
97	__attribute__((used)) int _lstat(const char* file, struct stat* st)
98	{
99	  size_t stoff = htif_win_store_str(0, file);
100	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
101	    return -1;
102	  htif_win_store(stoff, st, sizeof(*st));
103	  intptr_t ret =
104	    htif_syscall(VH_SYS_LSTAT, WIN_DATA_VA, WIN_DATA_VA + stoff, 0, 0);
105	  if (ret == 0)
106	    htif_win_load(st, stoff, sizeof(*st));
107	  return (int) ret;
108	}
109	
110	__attribute__((used)) int _fstatat(int dirfd, const char* file,
111	                                   struct stat* st, int flags)
112	{
113	  size_t stoff = htif_win_store_str(0, file);
114	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
115	    return -1;
116	  htif_win_store(stoff, st, sizeof(*st));
117	  intptr_t ret = htif_syscall(VH_SYS_FSTATAT, dirfd, WIN_DATA_VA,
118	                              WIN_DATA_VA + stoff, flags);
119	  if (ret == 0)
120	    htif_win_load(st, stoff, sizeof(*st));
121	  return (int) ret;
122	}
123	
124	__attribute__((used)) int _access(const char* file, int mode)
125	{
126	  return (int) htif_call_str(VH_SYS_ACCESS, file, mode, 0);
127	}
128	
129	__attribute__((used)) int _faccessat(int dirfd, const char* file, int mode,
130	                                     int flags)
131	{
132	  if (htif_win_store_str(0, file) == (size_t) -1)
133	    return -1;
134	  return (int) htif_syscall(VH_SYS_FACCESSAT, dirfd, WIN_DATA_VA, mode, flags);
135	}
136	
137	__attribute__((used)) int _link(const char* oldn, const char* newn)
138	{
139	  return (int) htif_call_str2(VH_SYS_LINK, oldn, newn);
140	}
141	
142	__attribute__((used)) int _unlink(const char* file)
143	{
144	  return (int) htif_call_str(VH_SYS_UNLINK, file, 0, 0);
145	}
146	
147	__attribute__((used)) int _rename(const char* oldn, const char* newn)
148	{
149	  return (int) htif_call_str2(VH_SYS_RENAME, oldn, newn);
150	}
151	
152	__attribute__((used)) int _getcwd(const char* buf, int size)
153	{
154	  size_t n = (size_t) size;
155	  if (n > WIN_DATA_SIZE)
156	    n = WIN_DATA_SIZE;
157	  intptr_t ret = htif_syscall(VH_SYS_GETCWD, WIN_DATA_VA, n, 0, 0);
158	  if (ret != 0)
159	    htif_win_load((void*) buf, 0, n);
160	  return (int) ret;
161	}
162	
163	__attribute__((used)) int _gettimeofday(struct timeval* tp, void* tzp)
164	{
165	  (void) tzp; /* both hosts ignore the timezone */
166	  intptr_t ret = htif_syscall(VH_SYS_GETTIMEOFDAY, WIN_DATA_VA, 0, 0, 0);
167	  if (ret == 0) {
168	    /* The host writes {sec, usec} at the target's register width -- the
169	     * same bytes the legacy protocol wrote into the guest's struct. */
170	    htif_win_load(tp, 0, __riscv_xlen == 64 ? 16 : 8);
171	  }
172	  return (int) ret;
173	}
174	
175	__attribute__((used)) int _kill(int pid, int sig)
176	{
177	  (void) pid;
178	  (void) sig;
179	  return -1;
180	}
181	
182	__attribute__((used)) int _getpid(void) { return 1; }
183	
184	__attribute__((used)) void* _sbrk(intptr_t increment)
185	{
186	  extern char _end[];
187	  static char* p = _end;
188	  void* base = p;
189	  p += increment;
190	  return base;
191	}
192	
193	/* Exit codes stay below 256: sim_control.hpp treats any command < 256 as
194	 * the raw exit code (the 0x0123456x magic commands live above). */
195	__attribute__((used, noreturn)) void _exit(int exit_status)
196	{
197	  *(volatile uint32_t*) SIM_EXIT_ADDR = (uint32_t) exit_status & 0xff;
198	  for (;;)
199	    ;
200	}
