18	/* ---- SimControl syscall window ------------------------------------------ */
19	
20	#define SYSCALL_GO_ADDR 0xe0080028UL
21	#define WIN_SLOTS ((volatile uint64_t*) 0xe0080800UL)
22	
23	/* Copy guest memory into the window data area (u64 stores only; the final
24	 * partial word over-stores into window slack, which is scratch). */
25	void htif_win_store(size_t woff, const void* src, size_t len)
26	{
27	  const unsigned char* s = (const unsigned char*) src;
28	  volatile uint64_t* w = (volatile uint64_t*) (WIN_DATA_VA + woff);
29	  while (len) {
30	    size_t n = len < 8 ? len : 8;
31	    uint64_t word = 0;
32	    for (size_t i = 0; i < n; ++i)
33	      word |= (uint64_t) s[i] << (8 * i);
34	    *w++ = word;
35	    s += n;
36	    len -= n;
37	  }
38	}
39	
40	/* Copy from the window data area into guest memory (u64 loads only). */
41	void htif_win_load(void* dst, size_t woff, size_t len)
42	{
43	  unsigned char* d = (unsigned char*) dst;
44	  volatile const uint64_t* w = (volatile const uint64_t*) (WIN_DATA_VA + woff);
45	  while (len) {
46	    size_t n = len < 8 ? len : 8;
47	    uint64_t word = *w++;
48	    for (size_t i = 0; i < n; ++i)
49	      d[i] = (unsigned char) (word >> (8 * i));
50	    d += n;
51	    len -= n;
52	  }
53	}
54	
55	size_t htif_win_store_str(size_t woff, const char* s)
56	{
57	  size_t len = 0;
58	  while (s[len])
59	    ++len;
60	  ++len; /* NUL */
61	  if (woff + len > WIN_DATA_SIZE)
62	    return (size_t) -1;
63	  htif_win_store(woff, s, len);
64	  return (woff + len + 7) & ~(size_t) 7;
65	}
66	
67	intptr_t htif_syscall(uint64_t n, uint64_t a0, uint64_t a1, uint64_t a2,
68	                       uint64_t a3)
69	{
70	  WIN_SLOTS[0] = n;
71	  WIN_SLOTS[1] = a0;
72	  WIN_SLOTS[2] = a1;
73	  WIN_SLOTS[3] = a2;
74	  WIN_SLOTS[4] = a3;
75	  WIN_SLOTS[5] = 0;
76	  WIN_SLOTS[6] = 0;
77	  WIN_SLOTS[7] = 0;
78	  *(volatile uint32_t*) SYSCALL_GO_ADDR = 1;
79	  __asm__ __volatile__("fence rw,rw" ::: "memory");
80	  return (intptr_t) WIN_SLOTS[0];
81	}
82	
83	intptr_t htif_call_str(uint64_t n, const char* s, uint64_t a1, uint64_t a2)
84	{
85	  if (htif_win_store_str(0, s) == (size_t) -1)
86	    return -1;
87	  return htif_syscall(n, WIN_DATA_VA, a1, a2, 0);
88	}
89	
90	intptr_t htif_call_str2(uint64_t n, const char* s0, const char* s1)
91	{
92	  size_t off1 = htif_win_store_str(0, s0);
93	  if (off1 == (size_t) -1 || htif_win_store_str(off1, s1) == (size_t) -1)
94	    return -1;
95	  return htif_syscall(n, WIN_DATA_VA, WIN_DATA_VA + off1, 0, 0);
96	}
97	
98	ssize_t htif_write(int fd, const void* ptr, size_t len)
99	{
100	  const unsigned char* p = (const unsigned char*) ptr;
101	  size_t done = 0;
102	  while (done < len) {
103	    size_t n = len - done;
104	    if (n > WIN_DATA_SIZE)
105	      n = WIN_DATA_SIZE;
106	    htif_win_store(0, p + done, n);
107	    intptr_t r = htif_syscall(VH_SYS_WRITE, fd, WIN_DATA_VA, n, 0);
108	    if (r < 0)
109	      return done ? (ssize_t) done : (ssize_t) r;
110	    done += (size_t) r;
111	    if ((size_t) r < n)
112	      break; /* short write */
113	  }
114	  return (ssize_t) done;
115	}
116	
117	ssize_t htif_read(int fd, void* buf, size_t len)
118	{
119	  unsigned char* p = (unsigned char*) buf;
120	  size_t done = 0;
121	  while (done < len) {
122	    size_t n = len - done;
123	    if (n > WIN_DATA_SIZE)
124	      n = WIN_DATA_SIZE;
125	    intptr_t r = htif_syscall(VH_SYS_READ, fd, WIN_DATA_VA, n, 0);
126	    if (r < 0)
127	      return done ? (ssize_t) done : (ssize_t) r;
128	    if (r > 0)
129	      htif_win_load(p + done, 0, (size_t) r);
130	    done += (size_t) r;
131	    if ((size_t) r < n)
132	      break; /* EOF or short read */
133	  }
134	  return (ssize_t) done;
135	}
136	
137	ssize_t htif_pread(int fd, void* buf, size_t len, long offset)
138	{
139	  intptr_t saved = htif_syscall(VH_SYS_LSEEK, (uint64_t) fd, 0, 1 /* SEEK_CUR */, 0);
140	  if (saved < 0)
141	    return (ssize_t) saved;
142	  intptr_t r = htif_syscall(VH_SYS_LSEEK, (uint64_t) fd, (uint64_t) offset,
143	                            0 /* SEEK_SET */, 0);
144	  if (r < 0)
145	    return (ssize_t) r;
146	  ssize_t n = htif_read(fd, buf, len);
147	  htif_syscall(VH_SYS_LSEEK, (uint64_t) fd, (uint64_t) saved, 0, 0);
148	  return n;
149	}
